import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist', 'failed_files': []}
    os.makedirs(dst_folder, exist_ok=True)
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        if os.path.isfile(file_path):
            compressed_path = file_path + '.gz'
            try:
                subprocess.run(['gzip', '-k', file_path], check=True)
                shutil.move(compressed_path, dst_folder)
            except Exception:
                failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else 'Some files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.isfile(script_path):
        raise FileNotFoundError("Script not found")

    cpu_usage_total = 0.0
    mem_usage_total = 0

    proc = subprocess.Popen(['bash', script_path], shell=False)
    start_time = time.time()
    while True:
        try:
            p = psutil.Process(proc.pid)
            cpu = p.cpu_percent(interval=0.1)
            mem = p.memory_info().rss
            cpu_usage_total += cpu
            mem_usage_total += mem
            if p.status() == psutil.STATUS_ZOMBIE:
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

        if time.time() - start_time > timeout:
            proc.terminate()
            break

        if proc.poll() is not None:
            break

    return {'CPU Usage': cpu_usage_total, 'Memory Usage': mem_usage_total}

